CREATE FUNCTION salud_u.buscar_historia_autorizada(p_paciente uuid, p_desde date DEFAULT NULL, p_hasta date DEFAULT NULL, p_termino text DEFAULT NULL)
RETURNS TABLE(id uuid, ocurrido_en timestamptz, tipo_encuentro text, estado text, motivo text, evaluacion text, especialidad text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = salud_u, pg_temp AS $$
DECLARE personal uuid := salud_u.id_mi_personal_activo(); termino text := nullif(lower(btrim(coalesce(p_termino, ''))), '');
BEGIN
  IF p_desde IS NOT NULL AND p_hasta IS NOT NULL AND p_desde > p_hasta THEN RAISE EXCEPTION 'RANGO_FECHAS_INVALIDO' USING ERRCODE = '22023'; END IF;
  IF NOT (salud_u.tiene_rol_actor('REVIEW_DOCTOR') OR salud_u.tiene_rol_actor('SPECIALIST')) THEN RAISE EXCEPTION 'MEDICO_NO_AUTORIZADO' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM salud_u.encuentro_clinico e WHERE e.id_paciente = p_paciente AND ((salud_u.tiene_rol_actor('REVIEW_DOCTOR') AND e.tipo_encuentro = 'INITIAL') OR (salud_u.tiene_rol_actor('SPECIALIST') AND ((e.tipo_encuentro = 'SPECIALTY' AND EXISTS (SELECT 1 FROM salud_u.especialidad_personal ep WHERE ep.id_personal = personal AND ep.id_especialidad = e.id_especialidad AND ep.vigente_desde <= current_date AND (ep.vigente_hasta IS NULL OR ep.vigente_hasta >= current_date))) OR (e.tipo_encuentro = 'INITIAL' AND EXISTS (SELECT 1 FROM salud_u.derivacion d WHERE d.id_encuentro_origen = e.id AND d.id_personal_asignado = personal)))))) THEN RAISE EXCEPTION 'PACIENTE_SIN_ACCESO_CLINICO' USING ERRCODE = 'P0002'; END IF;
  RETURN QUERY SELECT e.id, e.ocurrido_en, e.tipo_encuentro, e.estado, e.motivo_consulta, e.evaluacion, s.nombre FROM salud_u.encuentro_clinico e LEFT JOIN salud_u.especialidad s ON s.id = e.id_especialidad WHERE e.id_paciente = p_paciente AND (p_desde IS NULL OR e.ocurrido_en::date >= p_desde) AND (p_hasta IS NULL OR e.ocurrido_en::date <= p_hasta) AND (termino IS NULL OR lower(concat_ws(' ', e.motivo_consulta, e.evaluacion, e.indicaciones, e.seguimiento, s.nombre)) LIKE '%' || termino || '%') AND ((salud_u.tiene_rol_actor('REVIEW_DOCTOR') AND e.tipo_encuentro = 'INITIAL') OR (salud_u.tiene_rol_actor('SPECIALIST') AND ((e.tipo_encuentro = 'SPECIALTY' AND EXISTS (SELECT 1 FROM salud_u.especialidad_personal ep WHERE ep.id_personal = personal AND ep.id_especialidad = e.id_especialidad AND ep.vigente_desde <= current_date AND (ep.vigente_hasta IS NULL OR ep.vigente_hasta >= current_date))) OR (e.tipo_encuentro = 'INITIAL' AND EXISTS (SELECT 1 FROM salud_u.derivacion d WHERE d.id_encuentro_origen = e.id AND d.id_personal_asignado = personal))))) ORDER BY e.ocurrido_en DESC;
END;
$$;
CREATE INDEX encuentro_historia_busqueda_idx ON salud_u.encuentro_clinico(id_paciente, ocurrido_en DESC);
GRANT EXECUTE ON FUNCTION salud_u.buscar_historia_autorizada(uuid, date, date, text) TO ${runtime_role};
